 function normalize(value){return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[’‘`´]/g,"'").toLocaleLowerCase("en").replace(/[^a-z0-9]+/g," ").trim();}
 for(const [key,name,img] of entries){
  const record={key,name,img,url:BASE+img};
  if(!byName[normalize(name)])byName[normalize(name)]=record;
  if(!byKey[normalize(key.replace(/_/g," "))])byKey[normalize(key.replace(/_/g," "))]=record;
 }
 function resolve(name){const key=normalize(name),record=byName[key]||byKey[key];return record?record.url:null;}
 return Object.freeze({resolve,normalize,count:()=>entries.length});
